#include <stdio.h>
#define MAX 100

int soma(const int *ini, const int *fim) {
    int s = 0;
    while (ini < fim) {
        s += *ini;
        ini++;
    }
    return s;
}

const int *maior(const int *ini, const int *fim) {
    const int *m = ini;
    const int *p;
    for (p = ini + 1; p < fim; p++) {
        if (*p > *m) {
            m = p;
        }
    }
    return m;
}

void inverter(int *ini, int *fim) {
    int t;
    fim--;
    while (ini < fim) {
        t = *ini;
        *ini = *fim;
        *fim = t;
        ini++;
        fim--;
    }
}

int main(void) {
    int v[MAX];
    int n, i;
    const int *m;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", v + i);
    }
    printf("Soma: %d\n", soma(v, v + n));
    m = maior(v, v + n);
    printf("Maior: %d na posicao %d\n", *m, (int)(m - v));
    inverter(v, v + n);
    printf("Invertido:");
    for (i = 0; i < n; i++) {
        printf(" %d", *(v + i));
    }
    printf("\n");
