#include <stdio.h>
#define MAX 10

void ler(int m[][MAX], int linhas, int colunas) {
    int i, j;
    for (i = 0; i < linhas; i++) {
        for (j = 0; j < colunas; j++) {
            scanf("%d", &m[i][j]);
        }
    }
}

void multiplicar(int a[][MAX], int b[][MAX], int r[][MAX], int l, int m, int c) {
    int i, j, k;
    for (i = 0; i < l; i++) {
        for (j = 0; j < c; j++) {
            r[i][j] = 0;
            for (k = 0; k < m; k++) {
                r[i][j] += a[i][k] * b[k][j];
            }
        }
    }
}

int main(void) {
    int a[MAX][MAX], b[MAX][MAX], r[MAX][MAX];
    int l, m, c, i, j;
    int traco = 0;
    scanf("%d %d %d", &l, &m, &c);
    ler(a, l, m);
    ler(b, m, c);
    multiplicar(a, b, r, l, m, c);
    printf("Produto %dx%d:\n", l, c);
    for (i = 0; i < l; i++) {
        for (j = 0; j < c; j++) {
            if (j > 0) {
                printf(" ");
            }
            printf("%d", r[i][j]);
        }
        printf("\n");
    }
    if (l == c) {
        for (i = 0; i < l; i++) {
            traco += r[i][i];
        }
        printf("Traco: %d\n", traco);
    } else {
        printf("Traco: nao se aplica\n");
    }
    return 0;
}

