}

lessons.solution:
#include <stdio.h>
#include <ctype.h>

int main(void) {
    char linha[201];
    char *p;
    int resultado = 0;
    int numeros = 0;
    int sinal = 1;
    int valor;
    if (fgets(linha, 201, stdin) == NULL) {
        linha[0] = '\0';
    }
    p = linha;
    while (*p != '\0') {
        if (isspace(*p)) {
            p++;
        } else if (isdigit(*p)) {
            valor = 0;
            while (isdigit(*p)) {
                valor = valor * 10 + (*p - '0');
                p++;
            }
            resultado += sinal * valor;
            numeros++;
        } else if (*p == '+') {
            sinal = 1;
            p++;
        } else if (*p == '-') {
            sinal = -1;
            p++;
        } else {
            printf("Erro: caractere invalido '%c' na coluna %d\n", *p, (int)(p - linha) + 1);
            return 0;
        }
    }
    printf("Numeros: %d\n", numeros);
    printf("Resultado: %d\n", resultado);
    return 0;
}

