lessons.solution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int capacidade = 2;
    int n = 0;
    int x, i;
    int achou = 0;
    long soma = 0;
    double media;
    int *novo;
    int *v = malloc(capacidade * sizeof(int));
    if (v == NULL) {
        return 1;
    }
    while (scanf("%d", &x) == 1 && x != 0) {
        if (n == capacidade) {
            novo = realloc(v, 2 * capacidade * sizeof(int));
            if (novo == NULL) {
                free(v);
                return 1;
            }
            printf("Capacidade: %d -> %d\n", capacidade, 2 * capacidade);
            v = novo;
            capacidade = 2 * capacidade;
        }
        v[n] = x;
        n++;
        soma += x;
    }
    printf("Lidos: %d\n", n);
    if (n > 0) {
        media = (double)soma / n;
        printf("Media: %.2f\n", media);
        printf("Acima da media:");
        for (i = 0; i < n; i++) {
            if (v[i] > media) {
                printf(" %d", v[i]);
                achou = 1;
            }
        }
        if (!achou) {
            printf(" nenhum");
        }
        printf("\n");
    }
    free(v);
    return 0;
}

