#include <stdio.h>
#include <stdlib.h>

typedef struct No {
    int valor;
    struct No *prox;
} No;

No *inserirOrdenado(No *cabeca, int valor) {
    No *novo = malloc(sizeof(No));
    No *atual;
    novo->valor = valor;
    if (cabeca == NULL || valor < cabeca->valor) {
        novo->prox = cabeca;
        return novo;
    }
    atual = cabeca;
    while (atual->prox != NULL && atual->prox->valor <= valor) {
        atual = atual->prox;
    }
    novo->prox = atual->prox;
    atual->prox = novo;
    return cabeca;
}

No *remover(No *cabeca, int valor, int *removeu) {
    No *ant = NULL;
    No *atual = cabeca;
    while (atual != NULL && atual->valor != valor) {
        ant = atual;
        atual = atual->prox;
    }
    if (atual == NULL) {
        *removeu = 0;
        return cabeca;
    }
    if (ant == NULL) {
        cabeca = atual->prox;
    } else {
        ant->prox = atual->prox;
    }
    free(atual);
    *removeu = 1;
    return cabeca;
}

void mostrar(No *cabeca) {
    No *p;
    printf("Lista:");
    if (cabeca == NULL) {
        printf(" vazia");
    }
    for (p = cabeca; p != NULL; p = p->prox) {
        printf(" %d", p->valor);
    }
    printf("\n");
}

int main(void) {
    No *cabeca = NULL;
    No *prox;
    int n, i, valor, removeu;
    int tamanho = 0;
    char op;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf(" %c", &op);
        if (op == 'I') {
            scanf("%d", &valor);
            cabeca = inserirOrdenado(cabeca, valor);
        } else if (op == 'R') {
            scanf("%d", &valor);
            cabeca = remover(cabeca, valor, &removeu);
            if (!removeu) {
                printf("Nao encontrado: %d\n", valor);
            }
        } else if (op == 'P') {
            mostrar(cabeca);
        }
    }
    while (cabeca != NULL) {
        prox = cabeca->prox;
        free(cabeca);
        cabeca = prox;
        tamanho++;
    }
    printf("Tamanho: %d\n", tamanho);
    return 0;
}

