#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#define MAX 100

int pilha[MAX];
int topo = 0;

void empilhar(int x) {
    pilha[topo] = x;
    topo++;
}

int desempilhar(void) {
    topo--;
    return pilha[topo];
}

int main(void) {
    char tok[32];
    int a, b, i;
    char op;
    while (scanf("%s", tok) == 1) {
        if (isdigit(tok[0])) {
            empilhar(atoi(tok));
        } else if (strlen(tok) == 1 && strchr("+-*/", tok[0]) != NULL) {
            op = tok[0];
            if (topo < 2) {
                printf("Erro: faltam operandos para %c\n", op);
                return 0;
            }
            b = desempilhar();
            a = desempilhar();
            if (op == '+') {
                empilhar(a + b);
            } else if (op == '-') {
                empilhar(a - b);
            } else if (op == '*') {
                empilhar(a * b);
            } else {
                if (b == 0) {
                    printf("Erro: divisao por zero\n");
                    return 0;
                }
                empilhar(a / b);
            }
        } else {
            printf("Erro: token invalido %s\n", tok);
            return 0;
        }
        printf("%s =>", tok);
        for (i = 0; i < topo; i++) {
            printf(" %d", pilha[i]);
        }
        printf("\n");
    }
    if (topo == 1) {
        printf("Resultado: %d\n", pilha[0]);
    } else if (topo == 0) {
        printf("Erro: expressao vazia\n");
    } else {
        printf("Erro: sobraram %d valores\n", topo);
    }
    return 0;
}

