#include <stdio.h>

void mostrarBinario(unsigned int n) {
    int i;
    int comecou = 0;
    for (i = 31; i >= 0; i--) {
        if ((n >> i) & 1u) {
            putchar('1');
            comecou = 1;
        } else if (comecou) {
            putchar('0');
        }
    }
    if (!comecou) {
        putchar('0');
    }
}

int contarUns(unsigned int n) {
    int conta = 0;
    while (n != 0) {
        n = n & (n - 1);
        conta++;
    }
    return conta;
}

int main(void) {
    unsigned int n, mascara;
    int k;
    scanf("%u %d", &n, &k);
    printf("Binario: ");
    mostrarBinario(n);
    printf("\n");
    printf("Bits 1: %d\n", contarUns(n));
    if (n != 0 && (n & (n - 1)) == 0) {
        printf("Potencia de 2: sim\n");
    } else {
        printf("Potencia de 2: nao\n");
    }
    mascara = 1u << k;
    printf("Liga bit %d: %u\n", k, n | mascara);
    printf("Desliga bit %d: %u\n", k, n & ~mascara);
    printf("Inverte bit %d: %u\n", k, n ^ mascara);
    printf("Menor bit 1: %u\n", n & (~n + 1u));
    return 0;
}

