lessons.solution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define TAM 101
#define MAXP 1000

typedef struct Item {
    char palavra[31];
    int conta;
    struct Item *prox;
} Item;

Item *tabela[TAM];
Item *ordem[MAXP];
int distintas = 0;

unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s != '\0') {
        h = h * 33 + (unsigned char)*s;
        s++;
    }
    return h % TAM;
}

Item *buscarOuInserir(const char *palavra) {
    unsigned long b = hash(palavra);
    Item *it = tabela[b];
    while (it != NULL) {
        if (strcmp(it->palavra, palavra) == 0) {
            return it;
        }
        it = it->prox;
    }
    it = malloc(sizeof(Item));
    strcpy(it->palavra, palavra);
    it->conta = 0;
    it->prox = tabela[b];
    tabela[b] = it;
    ordem[distintas] = it;
    distintas++;
    return it;
}

int main(void) {
    int n, i;
    char palavra[31];
    Item *melhor;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%s", palavra);
        buscarOuInserir(palavra)->conta++;
    }
    melhor = ordem[0];
    for (i = 0; i < distintas; i++) {
        printf("%s: %d\n", ordem[i]->palavra, ordem[i]->conta);
        if (ordem[i]->conta > melhor->conta) {
            melhor = ordem[i];
        }
    }
    printf("Distintas: %d\n", distintas);
    printf("Mais frequente: %s (%d)\n", melhor->palavra, melhor->conta);
    for (i = 0; i < distintas; i++) {
        free(ordem[i]);
    }
    return 0;
}

