lessons.solution:
#include <stdio.h>
#define MAX 20

char grade[MAX][MAX + 1];
int dist[MAX][MAX];
int paiL[MAX][MAX], paiC[MAX][MAX];
int filaL[MAX * MAX], filaC[MAX * MAX];

int main(void) {
    int l, c, i, j, d;
    int sl = 0, sc = 0, el = 0, ec = 0;
    int ini = 0, fim = 0;
    int al, ac, nl, nc, pl;
    int dl[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    scanf("%d %d", &l, &c);
    for (i = 0; i < l; i++) {
        scanf("%s", grade[i]);
        for (j = 0; j < c; j++) {
            dist[i][j] = -1;
            if (grade[i][j] == 'S') {
                sl = i;
                sc = j;
            } else if (grade[i][j] == 'E') {
                el = i;
                ec = j;
            }
        }
    }
    dist[sl][sc] = 0;
    filaL[fim] = sl;
    filaC[fim] = sc;
    fim++;
    while (ini < fim) {
        al = filaL[ini];
        ac = filaC[ini];
        ini++;
        for (d = 0; d < 4; d++) {
            nl = al + dl[d];
            nc = ac + dc[d];
            if (nl < 0 || nl >= l || nc < 0 || nc >= c) {
                continue;
            }
            if (grade[nl][nc] == '#' || dist[nl][nc] != -1) {
                continue;
            }
            dist[nl][nc] = dist[al][ac] + 1;
            paiL[nl][nc] = al;
            paiC[nl][nc] = ac;
            filaL[fim] = nl;
            filaC[fim] = nc;
            fim++;
        }
    }
    if (dist[el][ec] == -1) {
        printf("Sem caminho\n");
        return 0;
    }
    printf("Distancia: %d\n", dist[el][ec]);
    i = paiL[el][ec];
    j = paiC[el][ec];
    while (!(i == sl && j == sc)) {
        grade[i][j] = '*';
        pl = paiL[i][j];
        j = paiC[i][j];
        i = pl;
    }
    for (i = 0; i < l; i++) {
        printf("%s\n", grade[i]);
    }
    return 0;
}
